    /** The program run on its own (no JCL step, no CICS task, no caller): the PROCEDURE DIVISION from its
     *  initial storage; RETURN-CODE. */
    public int runProgram() {
        initialState();
        performDepth = 0;
        try {
            perform(0, 2);
        } catch (Goback g) {
            // the program ended
        }
        return Cobol.num(f174_GG_RETURN_CODE, CS).intValue();
    }

    /** One task of the program: the EIB and COMMAREA from the task, then the PROCEDURE DIVISION. */
    public void runTask(CicsTask task) {
        boolean truncBefore = Cobol.swapTruncBinary(true);  // TRUNC(STD)
        boolean pfdBefore = Cobol.swapNumprocPfd(false);  // NUMPROC(NOPFD)
        try {
            this.task = task;
            caBack = () -> { };
            handlers.clear();
            heldKey.clear();
            initialState();
            Cobol.move(task.transid(), f145_EIBTRNID, CS);
            Cobol.move(task.termid() == null ? "" : task.termid(), f147_EIBTRMID, CS);
            Cobol.store(f146_EIBTASKN, BigDecimal.valueOf(task.taskNumber()), false, CS);
            java.time.LocalDateTime now = task.now();
            Cobol.store(f144_EIBDATE, BigDecimal.valueOf((now.getYear() - 1900) * 1000L + now.getDayOfYear()), false, CS);
            Cobol.store(f143_EIBTIME, BigDecimal.valueOf(now.getHour() * 10000L + now.getMinute() * 100L + now.getSecond()), false, CS);
            switch (task.aid() == null ? "" : task.aid()) {
                default -> { }
            }
            Object ca = task.hasCommarea() ? task.commarea(Object.class) : null;
            int calen = 0;
            if (ca instanceof Lgapvs01Dfhcommarea x) {
                in_Lgapvs01Dfhcommarea(x, s_DFHCOMMAREA, 0);
                caBack = () -> fill_Lgapvs01Dfhcommarea(x, s_DFHCOMMAREA, 0);
                calen = cx(task, 32500);
            } else if (ca instanceof LgstsqDfhcommarea x) {
                in_LgstsqDfhcommarea(x, s_DFHCOMMAREA, 0);
                caBack = () -> fill_LgstsqDfhcommarea(x, s_DFHCOMMAREA, 0);
                calen = cx(task, 99);
            }
            byte[] raw = task.linkArea();
            if (raw != null) {
                System.arraycopy(raw, 0, s_DFHCOMMAREA.bytes, 0, Math.min(raw.length, s_DFHCOMMAREA.bytes.length));
                Runnable typed = caBack;
                caBack = () -> { typed.run(); System.arraycopy(s_DFHCOMMAREA.bytes, 0, raw, 0, Math.min(raw.length, s_DFHCOMMAREA.bytes.length)); };
            }
            byte[] caWhole = null;
            if (task.exactCommarea() && calen < s_DFHCOMMAREA.bytes.length) {
                caWhole = s_DFHCOMMAREA.bytes;
                s_DFHCOMMAREA.bytes = java.util.Arrays.copyOf(caWhole, calen);
                Runnable typed = caBack;
                byte[] whole = caWhole;
                caBack = () -> { caWhole(whole); typed.run(); };
            }
            Cobol.store(f150_EIBCALEN, BigDecimal.valueOf(calen), false, CS);
            try {
                try {
                    perform(0, 2);
                } catch (Goback g) {
                    // RETURN / XCTL / an abend ended the program
                }
            } catch (IndexOutOfBoundsException e) {
                if (caWhole == null) {
                    throw e;
                }
                throw new DetCics.PastFrom("COMMAREA past EIBCALEN (" + calen + " bytes): not modelled");
            } finally {
                if (caWhole != null) {
                    caWhole(caWhole);
                }
            }
            if (!task.ended()) {
                caBack.run();
                task.returnTransid(null, null);  // a GOBACK is a RETURN
            }
        } finally {
            Cobol.swapTruncBinary(truncBefore);
            Cobol.swapNumprocPfd(pfdBefore);
        }
    }

    public Lgapvs01Dfhcommarea handleLink(Lgapvs01Dfhcommarea request) {
        CicsTask.Region region = CicsTask.region();
        CicsTask task = region.linked("LGAPVS01", request);
        region.run(task, "LGAPVS01", this::runTask);
        return request;
    }


    /** GOBACK / STOP RUN. */
    private static final class Goback extends RuntimeException {
        private static final long serialVersionUID = 1L;

        Goback() {
            super(null, null, false, false);
        }
    }

    /** The active PERFORMs' last paragraphs, outermost first. */
    private int[] performThru = new int[64];
    private int performDepth = 0;

    /** Control reached the end of an outer active PERFORM's range: that PERFORM returns (`depth`). */
    private static final class PerformExit extends RuntimeException {
        private static final long serialVersionUID = 1L;
        final int depth;

        PerformExit(int depth) {
            super(null, null, false, false);
            this.depth = depth;
        }
    }

    /** PERFORM from THRU thru. When control falls off the end of a paragraph, the innermost active PERFORM
     *  whose range ends there returns -- this one, or an outer one a GO TO reached the end of, abandoning
     *  the PERFORMs inside it (GnuCOBOL, as IBM: test_det_programs.py, GOTOOUT). */
    private void perform(int from, int thru) {
        int mine = performDepth;
        if (mine == performThru.length) {
            performThru = java.util.Arrays.copyOf(performThru, mine * 2);
        }
        performThru[performDepth++] = thru;
        try {
            int i = from;
            while (true) {
                int next = run(i);
                boolean jumped = (next & GOTO) != 0;
                next &= ~GOTO;
                if (!jumped) {
                    if (i == thru) {
                        return;
                    }
                    for (int d = mine - 1; d >= 0; d--) {
                        if (performThru[d] == i) {
                            throw new PerformExit(d);
                        }
                    }
                }
                if (next >= 3) {
                    throw new Goback();
                }
                i = next;
            }
        } catch (PerformExit e) {
            if (e.depth != mine) {
                throw e;
            }
        } finally {
            performDepth = mine;
        }
    }

    private int run(int i) {
        switch (i) {
            case 0: return p0();
            case 1: return p1();
            case 2: return p2();
            default: throw new IllegalStateException("paragraph " + i);
        }
    }

    /** MAINLINE. */
    private int p0() {
        // Move EIBCALEN To WS-Commarea-Len
        Cobol.move(f150_EIBCALEN, f6_WS_COMMAREA_LEN, CS);
        // Move CA-Request-ID(4:1) To WF-Request-ID
        Cobol.move(f57_CA_REQUEST_ID.ref(4, Integer.valueOf(1)), f9_WF_REQUEST_ID, CS);
        // Move CA-Policy-Num To WF-Policy-Num
        Cobol.move(f79_CA_POLICY_NUM, f11_WF_POLICY_NUM, CS);
        // Move CA-Customer-Num To WF-Customer-Num
        Cobol.move(f59_CA_CUSTOMER_NUM, f10_WF_CUSTOMER_NUM, CS);
        // Evaluate WF-Request-ID
        if ((Cobol.compare(f9_WF_REQUEST_ID, "C", CS) == 0)) {
            // Move CA-B-Postcode To WF-B-Postcode
            Cobol.move(f118_CA_B_POSTCODE, f14_WF_B_POSTCODE, CS);
            // Move CA-B-Status To WF-B-Status
            Cobol.move(f131_CA_B_STATUS, f15_WF_B_STATUS, CS);
            // Move CA-B-Customer To WF-B-Customer
            Cobol.move(f121_CA_B_CUSTOMER, f16_WF_B_CUSTOMER, CS);
        } else if ((Cobol.compare(f9_WF_REQUEST_ID, "E", CS) == 0)) {
            // Move CA-E-WITH-PROFITS To WF-E-WITH-PROFITS
            Cobol.move(f89_CA_E_WITH_PROFITS, f18_WF_E_WITH_PROFITS, CS);
            // Move CA-E-EQUITIES To WF-E-EQUITIES
            Cobol.move(f90_CA_E_EQUITIES, f19_WF_E_EQUITIES, CS);
            // Move CA-E-MANAGED-FUND To WF-E-MANAGED-FUND
            Cobol.move(f91_CA_E_MANAGED_FUND, f20_WF_E_MANAGED_FUND, CS);
            // Move CA-E-FUND-NAME To WF-E-FUND-NAME
            Cobol.move(f92_CA_E_FUND_NAME, f21_WF_E_FUND_NAME, CS);
            // Move CA-E-LIFE-ASSURED To WF-E-LIFE-ASSURED
            Cobol.move(f95_CA_E_LIFE_ASSURED, f22_WF_E_LIFE_ASSURED, CS);
        } else if ((Cobol.compare(f9_WF_REQUEST_ID, "H", CS) == 0)) {
            // Move CA-H-PROPERTY-TYPE To WF-H-PROPERTY-TYPE
            Cobol.move(f98_CA_H_PROPERTY_TYPE, f24_WF_H_PROPERTY_TYPE, CS);
            // Move CA-H-BEDROOMS To WF-H-BEDROOMS
            Cobol.move(f99_CA_H_BEDROOMS, f25_WF_H_BEDROOMS, CS);
            // Move CA-H-VALUE To WF-H-VALUE
            Cobol.move(f100_CA_H_VALUE, f26_WF_H_VALUE, CS);
            // Move CA-H-POSTCODE To WF-H-POSTCODE
            Cobol.move(f103_CA_H_POSTCODE, f27_WF_H_POSTCODE, CS);
            // Move CA-H-HOUSE-NAME To WF-H-HOUSE-NAME
            Cobol.move(f101_CA_H_HOUSE_NAME, f28_WF_H_HOUSE_NAME, CS);
        } else if ((Cobol.compare(f9_WF_REQUEST_ID, "M", CS) == 0)) {
            // Move CA-M-MAKE To WF-M-MAKE
            Cobol.move(f106_CA_M_MAKE, f30_WF_M_MAKE, CS);
            // Move CA-M-MODEL To WF-M-MODEL
            Cobol.move(f107_CA_M_MODEL, f31_WF_M_MODEL, CS);
            // Move CA-M-VALUE To WF-M-VALUE
            Cobol.move(f108_CA_M_VALUE, f32_WF_M_VALUE, CS);
            // Move CA-M-REGNUMBER To WF-M-REGNUMBER
            Cobol.move(f109_CA_M_REGNUMBER, f33_WF_M_REGNUMBER, CS);
        } else if (true) {
            // Move Spaces To WF-Policy-Data
            Cobol.moveFigurative(Figurative.SPACES, f12_WF_POLICY_DATA, CS);
        }
        // Exec CICS Write File('KSDSPOLY') From(WF-Policy-Info) Length(64) Ridfld(WF-Policy-Key) KeyLength(21) RESP(WS-RESP) End-Exec
        int resp1 = task.write("KSDSPOLY".strip(), store("KSDSPOLY".strip()).exists(DetCics.bytes(f8_WF_POLICY_KEY)), () -> store("KSDSPOLY".strip()).store(DetCics.bytes(f7_WF_POLICY_INFO, 64)));
        Cobol.store(f171_EIBRESP, BigDecimal.valueOf(resp1), false, CS);
        Cobol.store(f172_EIBRESP2, BigDecimal.valueOf(0), false, CS);
        f1_WS_RESP = Cobol.binary(BigDecimal.valueOf(resp1), 8, true, false, CS);
        // If WS-RESP Not = DFHRESP(NORMAL)
        if (!(f1_WS_RESP == 0L)) {
            // Move EIBRESP2 To WS-RESP2
            Cobol.move(f172_EIBRESP2, f2_WS_RESP2, CS);
            // MOVE '80' TO CA-RETURN-CODE
            Cobol.move("80", f58_CA_RETURN_CODE, CS);
            // PERFORM WRITE-ERROR-MESSAGE
            perform(2, 2);
            // EXEC CICS RETURN END-EXEC
            caBack.run();
            task.returnTransid(null, null);
            if (true) throw new Goback();
        }
        return 1;
    }

    /** A-EXIT. */
    private int p1() {
        // EXIT
        // GOBACK
        if (true) throw new Goback();
        return 2;
    }

    /** WRITE-ERROR-MESSAGE. */
    private int p2() {
        // EXEC CICS ASKTIME ABSTIME(WS-ABSTIME) END-EXEC
        Cobol.store(f34_WS_ABSTIME, BigDecimal.valueOf(task.asktime()), false, CS);
        // EXEC CICS FORMATTIME ABSTIME(WS-ABSTIME) MMDDYYYY(WS-DATE) TIME(WS-TIME) END-EXEC
        Cobol.move(CicsTask.formatDate(Cobol.num(f34_WS_ABSTIME, CS).longValue(), "MMDDYYYY", ""), f36_WS_DATE, CS);
        Cobol.move(CicsTask.formatTime(Cobol.num(f34_WS_ABSTIME, CS).longValue(), ""), f35_WS_TIME, CS);
        // MOVE WS-DATE TO EM-DATE
        Cobol.move(f36_WS_DATE, f38_EM_DATE, CS);
        // MOVE WS-TIME TO EM-TIME
        Cobol.move(f35_WS_TIME, f40_EM_TIME, CS);
        // Move CA-Customer-Num To EM-Cusnum
        Cobol.move(f59_CA_CUSTOMER_NUM, f46_EM_CUSNUM, CS);
        // Move CA-Policy-Num To EM-POLNUM
        Cobol.move(f79_CA_POLICY_NUM, f44_EM_POLNUM, CS);
        // Move WS-RESP To EM-RespRC
        Cobol.move(BigDecimal.valueOf(f1_WS_RESP), f49_EM_RESPRC, CS);
        // Move WS-RESP2 To EM-Resp2RC
        Cobol.move(f2_WS_RESP2, f51_EM_RESP2RC, CS);
        // EXEC CICS LINK PROGRAM('LGSTSQ') COMMAREA(ERROR-MSG) LENGTH(LENGTH OF ERROR-MSG) END-EXEC
        Storage cw4 = Cobol.commarea(f37_ERROR_MSG, 99);
        LgstsqDfhcommarea ca3 = out_LgstsqDfhcommarea(cw4, 0);
        String lr2 = task.link("LGSTSQ".strip(), ca3, BigDecimal.valueOf(101).intValue(), cw4.bytes);
        if ("NORMAL".equals(lr2)) { in_LgstsqDfhcommarea(ca3, cw4, 0); Cobol.commareaBack(cw4, f37_ERROR_MSG); }
        String exit5 = task.abendExit();
        if (exit5 != null) return GOTO | paragraph(exit5);
        if (task.ended()) throw abended();
        Cobol.store(f171_EIBRESP, BigDecimal.valueOf(DetCics.resp(lr2)), false, CS);
        Cobol.store(f172_EIBRESP2, BigDecimal.valueOf(0), false, CS);
        if (DetCics.resp(lr2) != 0) {
            int to = condition(DetCics.condition(DetCics.resp(lr2)));
            if (to >= 0) return GOTO | to;
        }
        // IF EIBCALEN > 0 THEN
        if (Cobol.num(f150_EIBCALEN, CS).compareTo(D0) > 0) {
            // IF EIBCALEN < 91 THEN
            if (Cobol.num(f150_EIBCALEN, CS).compareTo(D91) < 0) {
                // MOVE DFHCOMMAREA(1:EIBCALEN) TO CA-DATA
                Cobol.move(f56_DFHCOMMAREA.ref(1, Integer.valueOf(Cobol.num(f150_EIBCALEN, CS).intValue())), f54_CA_DATA, CS);
                // EXEC CICS LINK PROGRAM('LGSTSQ') COMMAREA(CA-ERROR-MSG) LENGTH(Length Of CA-ERROR-MSG) END-EXEC
                Storage cw8 = Cobol.commarea(f52_CA_ERROR_MSG, 99);
                LgstsqDfhcommarea ca7 = out_LgstsqDfhcommarea(cw8, 0);
                String lr6 = task.link("LGSTSQ".strip(), ca7, BigDecimal.valueOf(99).intValue(), cw8.bytes);
                if ("NORMAL".equals(lr6)) { in_LgstsqDfhcommarea(ca7, cw8, 0); Cobol.commareaBack(cw8, f52_CA_ERROR_MSG); }
                String exit9 = task.abendExit();
                if (exit9 != null) return GOTO | paragraph(exit9);
                if (task.ended()) throw abended();
                Cobol.store(f171_EIBRESP, BigDecimal.valueOf(DetCics.resp(lr6)), false, CS);
                Cobol.store(f172_EIBRESP2, BigDecimal.valueOf(0), false, CS);
                if (DetCics.resp(lr6) != 0) {
                    int to = condition(DetCics.condition(DetCics.resp(lr6)));
                    if (to >= 0) return GOTO | to;
                }
            } else {
                // MOVE DFHCOMMAREA(1:90) TO CA-DATA
                Cobol.move(f56_DFHCOMMAREA.ref(1, Integer.valueOf(90)), f54_CA_DATA, CS);
                // EXEC CICS LINK PROGRAM('LGSTSQ') COMMAREA(CA-ERROR-MSG) LENGTH(Length Of CA-ERROR-MSG) END-EXEC
                Storage cw12 = Cobol.commarea(f52_CA_ERROR_MSG, 99);
                LgstsqDfhcommarea ca11 = out_LgstsqDfhcommarea(cw12, 0);
                String lr10 = task.link("LGSTSQ".strip(), ca11, BigDecimal.valueOf(99).intValue(), cw12.bytes);
                if ("NORMAL".equals(lr10)) { in_LgstsqDfhcommarea(ca11, cw12, 0); Cobol.commareaBack(cw12, f52_CA_ERROR_MSG); }
                String exit13 = task.abendExit();
                if (exit13 != null) return GOTO | paragraph(exit13);
                if (task.ended()) throw abended();
                Cobol.store(f171_EIBRESP, BigDecimal.valueOf(DetCics.resp(lr10)), false, CS);
                Cobol.store(f172_EIBRESP2, BigDecimal.valueOf(0), false, CS);
                if (DetCics.resp(lr10) != 0) {
                    int to = condition(DetCics.condition(DetCics.resp(lr10)));
                    if (to >= 0) return GOTO | to;
                }
            }
        }
        // EXIT
        return 3;
    }

